    raw = json.load(f)

data = json.loads(raw['result'])
experiments = data['data']['experiments']

# The entity_construction experiment refers to n8_fair_cv, which has different deltas 
# from Table 1. The table says theta=2/N for N=8, so theta=0.25.
# Let me check the VC construction experiments - dgec_vc_construction has by_dataset details.
# Also check if there are experiments with 'qwen3' AND 'construction'

# Check all experiments for construction-related fields
construction_exps = []
for key, exp in experiments.items():
    m = exp.get('metrics', {})
    if isinstance(m, dict):
        for mk in m:
            if 'construction' in str(mk).lower():
                construction_exps.append(key)
                break
        # Also check nested
        for mk, mv in m.items():
            if isinstance(mv, dict):
                for mk2 in mv:
                    if 'construction' in str(mk2).lower():
                        if key not in construction_exps:
                            construction_exps.append(key)
                        break

print('Experiments with construction metrics:')
for k in sorted(construction_exps):
    print(f'  {k}')
